// Regenerates lib/grove/api/types.ts — one alias per daemon schema.
// Exhaustive by design: a curated list silently omits types consumers need.
import { readFileSync, writeFileSync } from "node:fs";

const SOURCE = "lib/grove/api/types.gen.ts";
const TARGET = "lib/grove/api/types.ts";

const names = [
  ...new Set(readFileSync(SOURCE, "utf8").match(/^ {8}\w+:/gm) ?? []),
]
  .map((line) => line.trim().slice(0, -1))
  // The generated file indents the `paths` block's HTTP verbs (`get`, `post`,
  // `requestBody`, …) to the same depth as a schema name, so match on shape:
  // schemas are PascalCase, those keys are not. `_`-prefixed schemas are the
  // daemon's internal request bodies and are not part of the public surface.
  .filter((name) => /^[A-Z]/.test(name))
  .sort();

writeFileSync(
  TARGET,
  `import type { components } from "./types.gen";\n\n` +
    `/**\n * The daemon's wire shapes, named — one alias per schema, no curation.\n *\n` +
    ` * Generated by scripts/gen-type-aliases.mjs. Do not hand-edit: a curated\n` +
    ` * subset was tried first and cost three workstreams a round trip each when a\n` +
    ` * type they plainly needed turned out not to be re-exported.\n */\n\n` +
    names.map((n) => `export type ${n} = components["schemas"]["${n}"];`).join("\n") +
    "\n",
);
console.log(`wrote ${names.length} aliases to ${TARGET}`);
